// ==================================================================
// GENERATORS
// ==================================================================

const math = []
const grammar = []
const spelling = []
const environment = []
const history = []
const religion = []
const geography = []
const science = []

// ---- MATH ----
function genAddition(n, mcRatio) {
  let made = 0
  let guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const a = randInt(15, 850)
    const b = randInt(15, 999 - a)
    const sum = a + b
    const isMc = rng() < mcRatio
    const q = `Πόσο κάνει ${a} + ${b};`
    const opts = isMc
      ? mcOptions(sum, [sum + 10, sum - 10, sum + 1, sum - 100 > 0 ? sum - 100 : sum + 100])
      : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, sum, opts)) made++
  }
}

function genSubtraction(n, mcRatio) {
  let made = 0
  let guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const a = randInt(20, 950)
    const b = randInt(10, a)
    const diff = a - b
    const isMc = rng() < mcRatio
    const q = `Πόσο κάνει ${a} - ${b};`
    const opts = isMc
      ? mcOptions(diff, [diff + 10, diff - 10 >= 0 ? diff - 10 : diff + 20, diff + 1])
      : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, diff, opts)) made++
  }
}

function genMultiplication(n, mcRatio) {
  const facts = []
  for (let a = 2; a <= 10; a++) for (let b = 2; b <= 10; b++) facts.push([a, b])
  const chosen = pickN(facts, Math.min(n, facts.length))
  for (const [a, b] of chosen) {
    const prod = a * b
    const isMc = rng() < mcRatio
    const q = `Πόσο κάνει ${a} x ${b};`
    const opts = isMc ? mcOptions(prod, [prod + a, prod - a, prod + b]) : undefined
    addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, prod, opts)
  }
}

function genDivision(n, mcRatio) {
  const facts = []
  for (let b = 2; b <= 10; b++) for (let q = 2; q <= 10; q++) facts.push([b * q, b, q])
  const chosen = pickN(facts, Math.min(n, facts.length))
  for (const [dividend, divisor, quotient] of chosen) {
    const isMc = rng() < mcRatio
    const q = `Πόσο κάνει ${dividend} : ${divisor};`
    const opts = isMc ? mcOptions(quotient, [quotient + 1, quotient - 1, divisor]) : undefined
    addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, quotient, opts)
  }
}

function genRounding(n) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const toHundred = rng() < 0.4
    const num = toHundred ? randInt(105, 985) : randInt(11, 995)
    const base = toHundred ? 100 : 10
    const rounded = Math.round(num / base) * base
    const q = `Στρογγυλοποίησε τον αριθμό ${num} στην πλησιέστερη ${toHundred ? 'εκατοντάδα' : 'δεκάδα'}.`
    const opts = mcOptions(rounded, [rounded + base, rounded - base, num])
    if (addQ(math, 'math', 'multiple-choice', q, rounded, opts)) made++
  }
}

function genGeometry(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(['square', 'rectangle', 'shape'])
    if (kind === 'square') {
      const side = randInt(2, 25)
      const perim = side * 4
      const isMc = rng() < mcRatio
      const q = `Ένα τετράγωνο έχει πλευρά ${side} εκατοστά. Ποια είναι η περίμετρός του;`
      const opts = isMc ? mcOptions(perim + ' εκ.', [(perim + side) + ' εκ.', (perim - side) + ' εκ.', (side * 2) + ' εκ.']) : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, perim + ' εκ.', opts, isMc ? undefined : cmAccepted(perim))) made++
    } else if (kind === 'rectangle') {
      const w = randInt(2, 20)
      const h = randInt(2, 20)
      if (w === h) continue
      const perim = 2 * (w + h)
      const isMc = rng() < mcRatio
      const q = `Ένα ορθογώνιο έχει πλευρές ${w} και ${h} εκατοστά. Ποια είναι η περίμετρός του;`
      const opts = isMc ? mcOptions(perim + ' εκ.', [(w * h) + ' εκ.', (perim + 2) + ' εκ.', (perim - 2) + ' εκ.']) : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, perim + ' εκ.', opts, isMc ? undefined : cmAccepted(perim))) made++
    } else {
      const shapes = [['τρίγωνο', 3], ['τετράγωνο', 4], ['πεντάγωνο', 5], ['εξάγωνο', 6]]
      const [name, sides] = pick(shapes)
      const q = `Πόσες πλευρές έχει ένα ${name};`
      const opts = mcOptions(sides, [sides + 1, sides - 1, sides + 2])
      if (addQ(math, 'math', 'multiple-choice', q, sides, opts)) made++
    }
  }
}

function genMeasurement(n, mcRatio) {
  let made = 0, guard = 0
  const kinds = ['kg', 'm', 'l']
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(kinds)
    let q, ans, unit
    if (kind === 'kg') {
      const kg = randInt(1, 9)
      unit = 'γραμμάρια'
      ans = kg * 1000
      q = `Πόσα γραμμάρια είναι ${kg} ${kg > 1 ? 'κιλά' : 'κιλό'};`
    } else if (kind === 'm') {
      const m = randInt(1, 9)
      unit = 'εκατοστά'
      ans = m * 100
      q = `Πόσα εκατοστά είναι ${m} ${m > 1 ? 'μέτρα' : 'μέτρο'};`
    } else {
      const l = randInt(1, 9)
      unit = 'χιλιοστόλιτρα (ml)'
      ans = l * 1000
      q = `Πόσα χιλιοστόλιτρα (ml) είναι ${l} ${l > 1 ? 'λίτρα' : 'λίτρο'};`
    }
    const isMc = rng() < mcRatio
    const opts = isMc ? mcOptions(ans, [ans / 10, ans + 100, ans - 100]) : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, ans, opts)) made++
  }
}

function genTime(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(['minutes', 'days', 'elapsed'])
    let q, ans
    if (kind === 'minutes') {
      const h = randInt(1, 5)
      q = `Πόσα λεπτά είναι ${h} ώρ${h > 1 ? 'ες' : 'α'};`
      ans = h * 60
    } else if (kind === 'days') {
      const w = randInt(1, 5)
      q = `Πόσες ημέρες είναι ${w} εβδομάδ${w > 1 ? 'ες' : 'α'};`
      ans = w * 7
    }
    let accepted
    if (kind === 'elapsed') {
      const startH = randInt(1, 10)
      const addH = randInt(1, 4)
      const endH = ((startH + addH - 1) % 12) + 1
      q = `Αν η ώρα είναι ${startH}:00, τι ώρα θα είναι σε ${addH} ώρες;`
      ans = `${endH}:00`
      accepted = [`${endH}`, `${endH}:00`, `${endH} η ώρα`]
    }
    const isMc = rng() < mcRatio
    const opts = isMc ? mcOptions(ans, [Number(ans) ? Number(ans) + 10 : ans, Number(ans) ? Number(ans) - 10 : ans, Number(ans) ? Number(ans) + 1 : ans]) : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, ans, opts, isMc ? undefined : accepted)) made++
  }
}

function genComparisonAndSequence(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(['parity', 'sequence', 'place-value'])
    if (kind === 'parity') {
      const nums = pickN([randInt(10, 99), randInt(10, 99), randInt(10, 99), randInt(10, 99)], 4)
      const odds = nums.filter((x) => x % 2 !== 0)
      if (odds.length === 0 || odds.length === 4) continue
      const target = pick(rng() < 0.5 ? nums.filter((x) => x % 2 !== 0) : nums.filter((x) => x % 2 === 0))
      const isOdd = target % 2 !== 0
      const q = `Ποιος αριθμός είναι ${isOdd ? 'μονός (περιττός)' : 'ζυγός (άρτιος)'};`
      const opts = mcOptions(target, nums.filter((x) => x !== target))
      if (opts.length < 2) continue
      if (addQ(math, 'math', 'multiple-choice', q, target, opts)) made++
    } else if (kind === 'sequence') {
      const step = pick([2, 3, 5, 10])
      const start = randInt(1, 20) * step
      const seq = [start, start + step, start + 2 * step, start + 3 * step, start + 4 * step]
      const missingIdx = randInt(2, 3)
      const answer = seq[missingIdx]
      const display = seq.map((v, i) => (i === missingIdx ? '__' : v)).join(', ')
      const q = `Ποιος αριθμός λείπει: ${display};`
      const isMc = rng() < mcRatio
      const opts = isMc ? mcOptions(answer, [answer + step, answer - step, answer + 1]) : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts)) made++
    } else {
      const h = randInt(1, 9)
      const t = randInt(0, 9)
      const u = randInt(0, 9)
      const num = h * 100 + t * 10 + u
      if (num < 100) continue
      const q = `Πόσες εκατοντάδες έχει ο αριθμός ${num};`
      const opts = mcOptions(h, [h + 1, h - 1 >= 0 ? h - 1 : h + 2, t])
      if (addQ(math, 'math', 'multiple-choice', q, h, opts)) made++
    }
  }
}

function genWordProblems(n, mcRatio) {
  let made = 0, guard = 0
  const templates = [
    () => {
      const name = pick(NAMES)
      const item = pick(ITEMS)
      const have = randInt(20, 90)
      const give = randInt(5, have - 5)
      const left = have - give
      return {
        q: `${fullName(name)} έχει ${have} ${item}. Δίνει ${give} σε έναν συμμαθητή. Πόσα ${item} μένουν;`,
        a: left,
      }
    },
    () => {
      const name = pick(NAMES)
      const item = pick(ITEMS)
      const price = randInt(1, 5)
      const count = randInt(2, 8)
      return {
        q: `${fullName(name)} αγόρασε ${count} ${item} των ${price}€ το καθένα. Πόσα ευρώ πλήρωσε συνολικά;`,
        a: `${price * count}€`,
        accepted: moneyAccepted(price * count),
      }
    },
    () => {
      const name = pick(NAMES)
      const item = pick(ITEMS)
      const total = randInt(20, 120)
      const groups = pick([2, 3, 4, 5, 6])
      if (total % groups !== 0) return null
      return {
        q: `${fullName(name)} έχει ${total} ${item} και τα μοιράζει εξίσου σε ${groups} φίλους. Πόσα ${item} παίρνει ο καθένας;`,
        a: total / groups,
      }
    },
    () => {
      const nameA = pick(NAMES)
      const nameB = pick(NAMES.filter((n) => n.name !== nameA.name))
      const item = pick(ITEMS)
      const a = randInt(10, 60)
      const b = randInt(10, 60)
      if (a === b) return null
      const diff = Math.abs(a - b)
      const more = a > b ? nameA : nameB
      return {
        q: `${fullName(nameA)} έχει ${a} ${item} και ${midSentenceName(nameB)} έχει ${b} ${item}. Πόσα ${item} περισσότερα έχει ${midSentenceName(more)};`,
        a: diff,
      }
    },
    () => {
      const name = pick(NAMES)
      const total = randInt(10, 50) * 2
      const frac = pick([2, 3, 4])
      if (total % frac !== 0) return null
      const eaten = total / frac
      const fracWord = frac === 2 ? 'το μισό' : frac === 3 ? 'το 1/3' : 'το 1/4'
      return {
        q: `${fullName(name)} έχει ${total} ${pick(ITEMS)}. Έφαγε ${fracWord}. Πόσα έφαγε;`,
        a: eaten,
      }
    },
    () => {
      const name = pick(NAMES)
      const price = randInt(2, 8)
      const paid = randInt(10, 20)
      if (paid <= price) return null
      return {
        q: `${fullName(name)} αγόρασε ένα παιχνίδι που κοστίζει ${price}€ και πλήρωσε με χαρτονόμισμα των ${paid}€. Πόσα ρέστα πήρε;`,
        a: `${paid - price}€`,
        accepted: moneyAccepted(paid - price),
      }
    },
    () => {
      const name = pick(NAMES)
      const born = randInt(2016, 2019)
      const year = randInt(2026, 2029)
      return {
        q: `${fullName(name)} γεννήθηκε το ${born}. Πόσων χρονών θα είναι το ${year};`,
        a: year - born,
      }
    },
    () => {
      const name = pick(NAMES)
      const item = pick(ITEMS)
      const box = randInt(5, 12)
      const boxes = randInt(3, 9)
      return {
        q: `${fullName(name)} έχει ${boxes} κουτιά με ${box} ${item} το καθένα. Πόσα ${item} έχει συνολικά;`,
        a: box * boxes,
      }
    },
  ]
  while (made < n && guard < n * 30) {
    guard++
    const result = pick(templates)()
    if (!result) continue
    const isMc = rng() < mcRatio && typeof result.a !== 'string'
    let opts
    if (isMc) {
      const base = Number(result.a)
      opts = mcOptions(result.a, [base + randInt(1, 5), base - randInt(1, 5), base + 10])
    }
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', result.q, result.a, opts, isMc ? undefined : result.accepted)) made++
  }
}

// ---- GRAMMAR ----
function genArticles(n) {
  const chosen = pickN(NOUNS, Math.min(n, NOUNS.length))
  for (const [word, article] of chosen) {
    const q = `Ποιο άρθρο ταιριάζει: ___ ${word}`
    const opts = mcOptions(article, ['ο', 'η', 'το'])
    addQ(grammar, 'grammar', 'multiple-choice', q, article, opts)
  }
}

function genGender(n) {
  const genderLabel = { ο: 'Αρσενικό', η: 'Θηλυκό', το: 'Ουδέτερο' }
  const chosen = pickN(NOUNS, Math.min(n, NOUNS.length))
  for (const [word, article] of chosen) {
    const q = `Ποιο είναι το γένος της λέξης «${word}»;`
    const answer = genderLabel[article]
    const opts = mcOptions(answer, ['Αρσενικό', 'Θηλυκό', 'Ουδέτερο'])
    addQ(grammar, 'grammar', 'multiple-choice', q, answer, opts)
  }
}

function genPluralText(n) {
  const chosen = pickN(NOUNS, Math.min(n, NOUNS.length))
  const pluralArticle = { ο: 'οι', η: 'οι', το: 'τα' }
  for (const [word, article, plural] of chosen) {
    const q = `Γράψε τον πληθυντικό αριθμό της λέξης «${article} ${word}».`
    addQ(grammar, 'grammar', 'text', q, `${pluralArticle[article]} ${plural}`)
  }
}

function genNumber(n) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const [word, article, plural] = pick(NOUNS)
    const useSingular = rng() < 0.5
    const form = useSingular ? word : plural
    const answer = useSingular ? 'Ενικός αριθμός' : 'Πληθυντικός αριθμός'
    const q = `Η λέξη «${form}» βρίσκεται σε:`
    const opts = mcOptions(answer, ['Ενικός αριθμός', 'Πληθυντικός αριθμός'])
    if (addQ(grammar, 'grammar', 'multiple-choice', q, answer, opts)) made++
  }
}

// αιτιατική («στον Παρατατικό»), όπως διαβάζεται μέσα στην εκφώνηση
const TENSE_LABELS = ['Ενεστώτα', 'Παρατατικό', 'Αόριστο', 'Μέλλοντα']
function genVerbTenses(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const [base, firstPerson, thirdPerson] = pick(VERBS)
    const tense = randInt(0, 2) // παρατατικός/αόριστος/μέλλοντας
    const answer = firstPerson[tense]
    const q = `Το ρήμα «${base}» στον ${TENSE_LABELS[tense + 1]} γίνεται:`
    const isMc = rng() < mcRatio
    let opts
    if (isMc) {
      const otherVerb = pick(VERBS.filter((v) => v[0] !== base))
      const distractors = [
        ...firstPerson.filter((_, i) => i !== tense),
        otherVerb[1][tense],
      ]
      opts = mcOptions(answer, distractors)
    }
    // text answers in γ' ενικό (e.g. «έπαιξε») are equally correct
    const accepted = isMc ? undefined : [thirdPerson[tense]]
    if (addQ(grammar, 'grammar', isMc ? 'multiple-choice' : 'text', q, answer, opts, accepted)) made++
  }
}

function genSynonyms(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const pair = pick(SYNONYM_PAIRS)
    const reversed = rng() < 0.5
    const [word, syn] = reversed ? [pair[1], pair[0]] : pair
    const extras = pair[2] ?? []
    const isMc = rng() < mcRatio
    const q = isMc ? `Ποιο είναι το συνώνυμο της λέξης «${word}»;` : `Γράψε ένα συνώνυμο της λέξης «${word}».`
    let opts
    if (isMc) {
      const distractorPairs = SYNONYM_PAIRS.filter((p) => p !== pair)
      const distractors = pickN(distractorPairs, 3).map((p) => pick(p.slice(0, 2)))
      opts = mcOptions(syn, distractors)
    }
    // in text mode the extra synonyms also count as correct
    const accepted = isMc ? undefined : extras.filter((w) => w !== syn && w !== word)
    if (addQ(grammar, 'grammar', isMc ? 'multiple-choice' : 'text', q, syn, opts, accepted)) made++
  }
}

function genAntonyms(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const pair = pick(ANTONYM_PAIRS)
    const reversed = rng() < 0.5
    const [word, ant] = reversed ? [pair[1], pair[0]] : pair
    const isMc = rng() < mcRatio
    const q = isMc ? `Ποιο είναι το αντίθετο της λέξης «${word}»;` : `Γράψε το αντίθετο της λέξης «${word}».`
    let opts
    if (isMc) {
      const distractorPairs = ANTONYM_PAIRS.filter((p) => p !== pair)
      const distractors = pickN(distractorPairs, 3).map((p) => pick(p))
      opts = mcOptions(ant, distractors)
    }
    if (addQ(grammar, 'grammar', isMc ? 'multiple-choice' : 'text', q, ant, opts)) made++
  }
}

function genSentenceTypes(n) {
  const chosen = pickN(SENTENCES, Math.min(n, SENTENCES.length))
  for (const [sentence, type] of chosen) {
    const q = `Τι είδους πρόταση είναι: «${sentence}»`
    const opts = mcOptions(type, SENTENCE_TYPES)
    addQ(grammar, 'grammar', 'multiple-choice', q, type, opts)
  }
}

function genPartsOfSpeech(n) {
  const pools = {
    Ουσιαστικό: NOUNS.map((x) => x[0]),
    Επίθετο: ADJECTIVES,
    Ρήμα: VERBS.map((x) => x[0]),
    Επίρρημα: ADVERBS,
  }
  const types = Object.keys(pools)
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const targetType = pick(types)
    const correctWord = pick(pools[targetType])
    const distractors = types
      .filter((t) => t !== targetType)
      .map((t) => pick(pools[t]))
    const q = `Ποια λέξη είναι ${targetType.toLowerCase()};`
    const opts = shuffle([correctWord, ...distractors])
    if (addQ(grammar, 'grammar', 'multiple-choice', q, correctWord, opts)) made++
  }
}

// ---- ENVIRONMENT ----
function genEnvironment(list = ENVIRONMENT_QUESTIONS) {
  genFactBank(environment, 'environment', list)
}

// ---- HISTORY / RELIGION / GEOGRAPHY / SCIENCE ----
// same hand-written [question, answer, wrongs|null, acceptedAnswers?] format as Environment
function genFactBank(bucket, category, list) {
  for (const [q, answer, wrongs, accepted] of list) {
    if (wrongs) {
      addQ(bucket, category, 'multiple-choice', q, answer, mcOptions(answer, wrongs))
    } else {
      addQ(bucket, category, 'text', q, answer, undefined, accepted)
    }
  }
}
function genHistory(list) {
  genFactBank(history, 'history', list)
}
function genReligion(list) {
  genFactBank(religion, 'religion', list)
}
function genGeography(list) {
  genFactBank(geography, 'geography', list)
}
function genScience(list) {
  genFactBank(science, 'science', list)
}

// ---- SPELLING ----
function genSpelling(n, mcRatio, wordList = SPELLING_WORDS) {
  const withVariants = wordList.map((w) => ({ w, v: buildSpellingVariants(w) })).filter((x) => x.v)
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const entry = pick(withVariants)
    const { correct, wrongs } = entry.v
    const wantMc = rng() < mcRatio && wrongs.length >= 1
    if (wantMc) {
      const distractors = wrongs.length >= 3 ? pickN(wrongs, 3) : [...wrongs, ...pickN(wrongs, 3 - wrongs.length)]
      const q = 'Ποια γραφή είναι σωστή;'
      const opts = mcOptions(correct, distractors)
      if (addQ(spelling, 'spelling', 'multiple-choice', q, correct, opts)) made++
    } else {
      const match = findConfusionMatch(correct)
      const { key, idx } = match
      // one underscore per missing letter, and the expected answer is
      // just those letters (the full word is accepted too)
      const blanked = correct.slice(0, idx) + '_'.repeat(key.length) + correct.slice(idx + key.length)
      const what = key.length > 1 ? 'τα γράμματα που λείπουν' : 'το γράμμα που λείπει'
      const q = `Συμπλήρωσε ${what}: ${blanked}`
      if (addQ(spelling, 'spelling', 'text', q, key, undefined, [correct])) made++
    }
  }
}

// ==================================================================
// Δ' ΔΗΜΟΤΙΚΟΥ — data & generators
// ==================================================================

// αριθμοί ως 10.000, δεκαδικοί, εμβαδόν, διαίρεση με υπόλοιπο
function genAdditionD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const a = randInt(150, 8500)
    const b = randInt(150, 9999 - a)
    const sum = a + b
    const isMc = rng() < mcRatio
    const q = `Πόσο κάνει ${a} + ${b};`
    const opts = isMc ? mcOptions(sum, [sum + 100, sum - 100, sum + 10]) : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, sum, opts)) made++
  }
}

function genSubtractionD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const a = randInt(500, 9900)
    const b = randInt(100, a - 50)
    const diff = a - b
    const isMc = rng() < mcRatio
    const q = `Πόσο κάνει ${a} - ${b};`
    const opts = isMc ? mcOptions(diff, [diff + 100, diff - 100 > 0 ? diff - 100 : diff + 200, diff + 10]) : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, diff, opts)) made++
  }
}

function genMultiplicationD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(['2x1', '3x1', 'x10', 'x100'])
    let a, b
    if (kind === '2x1') { a = randInt(12, 99); b = randInt(3, 9) }
    else if (kind === '3x1') { a = randInt(102, 400); b = randInt(2, 5) }
    else if (kind === 'x10') { a = randInt(12, 99); b = 10 }
    else { a = randInt(3, 60); b = 100 }
    const prod = a * b
    const isMc = rng() < mcRatio
    const q = `Πόσο κάνει ${a} x ${b};`
    const opts = isMc ? mcOptions(prod, [prod + b, prod - b, prod + 10 * b]) : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, prod, opts)) made++
  }
}

function genDivisionD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(['remainder-q', 'remainder-r', 'exact10'])
    if (kind === 'exact10') {
      const b = pick([10, 100])
      const quotient = randInt(3, 90)
      const a = quotient * b
      const isMc = rng() < mcRatio
      const q = `Πόσο κάνει ${a} : ${b};`
      const opts = isMc ? mcOptions(quotient, [quotient * 10, Math.max(1, Math.round(quotient / 10)), quotient + 1]) : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, quotient, opts)) made++
    } else {
      const b = randInt(3, 9)
      const quotient = randInt(4, 30)
      const r = randInt(1, b - 1)
      const a = b * quotient + r
      const askQuotient = kind === 'remainder-q'
      const answer = askQuotient ? quotient : r
      const isMc = rng() < mcRatio
      const q = `Στη διαίρεση ${a} : ${b}, ποιο είναι το ${askQuotient ? 'πηλίκο' : 'υπόλοιπο'};`
      const opts = isMc
        ? mcOptions(answer, askQuotient ? [quotient + 1, quotient - 1, r] : [r + 1, b - r, quotient])
        : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts)) made++
    }
  }
}

const asDecimal = (cents) => (cents / 100).toFixed(2).replace(/0$/, '').replace(/\.$/, '').replace('.', ',')
const decimalAccepted = (cents, suffix = '') => {
  const comma = asDecimal(cents)
  const dot = comma.replace(',', '.')
  const list = [comma, dot]
  if (suffix) list.push(`${comma}${suffix}`, `${dot}${suffix}`, `${comma} ${suffix.trim()}`)
  return [...new Set(list)]
}

function genDecimalsD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(['fraction', 'money-add', 'compare'])
    if (kind === 'fraction') {
      const tenths = rng() < 0.6
      const num = tenths ? randInt(1, 9) : randInt(1, 99)
      const den = tenths ? 10 : 100
      const cents = tenths ? num * 10 : num
      const answer = asDecimal(cents)
      const isMc = rng() < mcRatio
      const q = `Πώς γράφεται το κλάσμα ${num}/${den} ως δεκαδικός αριθμός;`
      const wrongA = asDecimal(cents * 10 <= 999 ? cents * 10 : cents + 10)
      const wrongB = asDecimal(Math.max(1, Math.round(cents / 10)))
      const opts = isMc ? mcOptions(answer, [wrongA, wrongB, String(num)]) : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts, isMc ? undefined : decimalAccepted(cents))) made++
    } else if (kind === 'money-add') {
      const a = randInt(105, 1500)
      const b = randInt(105, 1500)
      const sum = a + b
      const q = `Πόσο κάνει ${asDecimal(a)}€ + ${asDecimal(b)}€;`
      const isMc = rng() < mcRatio
      const answer = `${asDecimal(sum)}€`
      const opts = isMc ? mcOptions(answer, [`${asDecimal(sum + 100)}€`, `${asDecimal(sum - 100)}€`, `${asDecimal(sum + 10)}€`]) : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts, isMc ? undefined : decimalAccepted(sum, '€'))) made++
    } else {
      const a = randInt(11, 99)
      const b = randInt(11, 99)
      if (a === b) continue
      const bigger = Math.max(a, b)
      const q = `Ποιος αριθμός είναι μεγαλύτερος;`
      const opts = mcOptions(asDecimal(bigger * 10) , [asDecimal(Math.min(a, b) * 10)])
      if (opts.length < 2) continue
      if (addQ(math, 'math', 'multiple-choice', q + ` ${asDecimal(a * 10)} ή ${asDecimal(b * 10)};`, asDecimal(bigger * 10), mcOptions(asDecimal(bigger * 10), [asDecimal(Math.min(a, b) * 10)]))) made++
    }
  }
}

function genFractionsD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const kind = pick(['equivalent', 'compare', 'whole'])
    if (kind === 'equivalent') {
      const base = pick([[1, 2], [1, 3], [1, 4], [2, 3], [3, 4]])
      const k = pick([2, 3, 4])
      const answer = base[0] * k
      const q = `Συμπλήρωσε το ισοδύναμο κλάσμα: ${base[0]}/${base[1]} = ;/${base[1] * k}`
      const isMc = rng() < mcRatio
      const opts = isMc ? mcOptions(answer, [answer + 1, answer - 1 > 0 ? answer - 1 : answer + 2, base[1] * k]) : undefined
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts)) made++
    } else if (kind === 'compare') {
      const den = pick([5, 6, 7, 8, 9, 10])
      const a = randInt(1, den - 1)
      const b = randInt(1, den - 1)
      if (a === b) continue
      const bigger = Math.max(a, b)
      const q = `Ποιο κλάσμα είναι μεγαλύτερο: ${a}/${den} ή ${b}/${den};`
      const opts = mcOptions(`${bigger}/${den}`, [`${Math.min(a, b)}/${den}`])
      if (addQ(math, 'math', 'multiple-choice', q, `${bigger}/${den}`, opts)) made++
    } else {
      const den = pick([2, 3, 4, 5, 6, 8, 10])
      const q = `Ποιο κλάσμα ισούται με μία ολόκληρη μονάδα;`
      const opts = mcOptions(`${den}/${den}`, [`${den}/${den + 1}`, `1/${den}`, `${den - 1}/${den}`])
      if (addQ(math, 'math', 'multiple-choice', q, `${den}/${den}`, opts)) made++
    }
  }
}

function genAreaD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const square = rng() < 0.4
    if (square) {
      const side = randInt(3, 20)
      const area = side * side
      const isMc = rng() < mcRatio
      const q = `Ένα τετράγωνο έχει πλευρά ${side} εκατοστά. Ποιο είναι το εμβαδόν του;`
      const answer = `${area} τ.εκ.`
      const opts = isMc ? mcOptions(answer, [`${side * 4} τ.εκ.`, `${area + side} τ.εκ.`, `${area - side} τ.εκ.`]) : undefined
      const accepted = isMc ? undefined : [`${area}`, `${area} τ.εκ`, `${area} τ.εκ.`, `${area} τετραγωνικά εκατοστά`]
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts, accepted)) made++
    } else {
      const w = randInt(3, 25)
      const h = randInt(3, 25)
      if (w === h) continue
      const area = w * h
      const isMc = rng() < mcRatio
      const q = `Ένα ορθογώνιο έχει μήκος ${w} και πλάτος ${h} εκατοστά. Ποιο είναι το εμβαδόν του;`
      const answer = `${area} τ.εκ.`
      const opts = isMc ? mcOptions(answer, [`${2 * (w + h)} τ.εκ.`, `${area + w} τ.εκ.`, `${area - h} τ.εκ.`]) : undefined
      const accepted = isMc ? undefined : [`${area}`, `${area} τ.εκ`, `${area} τ.εκ.`, `${area} τετραγωνικά εκατοστά`]
      if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts, accepted)) made++
    }
  }
}

function genRoundingD(n) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const toThousand = rng() < 0.5
    const num = toThousand ? randInt(1050, 9950) : randInt(105, 9985)
    const base = toThousand ? 1000 : 100
    const rounded = Math.round(num / base) * base
    const q = `Στρογγυλοποίησε τον αριθμό ${num} στην πλησιέστερη ${toThousand ? 'χιλιάδα' : 'εκατοντάδα'}.`
    const opts = mcOptions(rounded, [rounded + base, rounded - base, num])
    if (addQ(math, 'math', 'multiple-choice', q, rounded, opts)) made++
  }
}

function genTimeD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const startH = randInt(1, 11)
    const startM = pick([0, 15, 30, 45])
    const addM = pick([20, 30, 45, 50, 70, 90])
    const total = startH * 60 + startM + addM
    const endH = Math.floor(total / 60) > 12 ? Math.floor(total / 60) - 12 : Math.floor(total / 60)
    const endM = total % 60
    const answer = `${endH}:${String(endM).padStart(2, '0')}`
    const startStr = `${startH}:${String(startM).padStart(2, '0')}`
    const q = `Η ώρα είναι ${startStr}. Τι ώρα θα είναι σε ${addM} λεπτά;`
    const isMc = rng() < mcRatio
    const wrong1 = `${endH}:${String((endM + 10) % 60).padStart(2, '0')}`
    const wrong2 = `${(endH % 12) + 1}:${String(endM).padStart(2, '0')}`
    const opts = isMc ? mcOptions(answer, [wrong1, wrong2]) : undefined
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', q, answer, opts)) made++
  }
}

function genWordProblemsD(n, mcRatio) {
  let made = 0, guard = 0
  const templates = [
    () => {
      const name = pick(NAMES)
      const item = pick(ITEMS)
      const count = randInt(3, 9)
      const price = randInt(2, 8)
      const paid = pick([20, 50])
      const cost = count * price
      if (cost >= paid) return null
      return {
        q: `${fullName(name)} αγόρασε ${count} ${item} των ${price}€ το καθένα και πλήρωσε με ${paid}€. Πόσα ρέστα πήρε;`,
        a: `${paid - cost}€`,
        accepted: moneyAccepted(paid - cost),
      }
    },
    () => {
      const name = pick(NAMES)
      const total = randInt(4, 9) * 100
      const spent1 = randInt(50, 200)
      const spent2 = randInt(50, 200)
      if (spent1 + spent2 >= total) return null
      return {
        q: `${fullName(name)} είχε ${total}€. Ξόδεψε ${spent1}€ για ρούχα και ${spent2}€ για παπούτσια. Πόσα ευρώ έμειναν;`,
        a: `${total - spent1 - spent2}€`,
        accepted: moneyAccepted(total - spent1 - spent2),
      }
    },
    () => {
      const name = pick(NAMES)
      const rows = randInt(12, 30)
      const perRow = randInt(12, 25)
      return {
        q: `Σε ένα θέατρο υπάρχουν ${rows} σειρές με ${perRow} καθίσματα η καθεμία. Πόσα καθίσματα έχει συνολικά; (${name.name} θέλει να το υπολογίσει!)`,
        a: rows * perRow,
      }
    },
    () => {
      const name = pick(NAMES)
      const km = randInt(120, 480)
      const done = randInt(40, km - 40)
      return {
        q: `${fullName(name)} ταξιδεύει ${km} χιλιόμετρα. Έχει διανύσει ήδη ${done}. Πόσα χιλιόμετρα μένουν ακόμα;`,
        a: km - done,
      }
    },
    () => {
      const name = pick(NAMES)
      const kids = pick([3, 4, 5, 6])
      const each = randInt(15, 60)
      return {
        q: `${fullName(name)} μοιράζει εξίσου ${kids * each} καραμέλες σε ${kids} παιδιά. Πόσες παίρνει το καθένα;`,
        a: each,
      }
    },
  ]
  while (made < n && guard < n * 30) {
    guard++
    const result = pick(templates)()
    if (!result) continue
    const isMc = rng() < mcRatio && typeof result.a !== 'string'
    let opts
    if (isMc) {
      const base = Number(result.a)
      opts = mcOptions(result.a, [base + randInt(2, 9), base - randInt(2, 9), base + 20])
    }
    if (addQ(math, 'math', isMc ? 'multiple-choice' : 'text', result.q, result.a, opts, isMc ? undefined : result.accepted)) made++
  }
}

// --- Γραμματική Δ' ---
const TENSE_LABELS_D = ['Παρατατικό', 'Αόριστο', 'Μέλλοντα', 'Παρακείμενο']
function genVerbTensesD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const [base, firstPerson, thirdPerson] = pick(VERBS)
    const aparemfato = thirdPerson[2].replace(/^θα /, '')
    const first = [...firstPerson, `έχω ${aparemfato}`]
    const third = [...thirdPerson, `έχει ${aparemfato}`]
    const tense = randInt(0, 3)
    const answer = first[tense]
    const q = `Το ρήμα «${base}» στον ${TENSE_LABELS_D[tense]} γίνεται:`
    const isMc = rng() < mcRatio
    let opts
    if (isMc) {
      const otherVerb = pick(VERBS.filter((v) => v[0] !== base))
      const otherAp = otherVerb[2][2].replace(/^θα /, '')
      const otherFirst = [...otherVerb[1], `έχω ${otherAp}`]
      opts = mcOptions(answer, [...first.filter((_, i) => i !== tense), otherFirst[tense]])
    }
    const accepted = isMc ? undefined : [third[tense]]
    if (addQ(grammar, 'grammar', isMc ? 'multiple-choice' : 'text', q, answer, opts, accepted)) made++
  }
}

// [θετικός, συγκριτικός, υπερθετικός]
const COMPARATIVES = [
  ['ψηλός', 'ψηλότερος', 'ψηλότατος'], ['μεγάλος', 'μεγαλύτερος', 'μέγιστος'],
  ['μικρός', 'μικρότερος', 'ελάχιστος'], ['καλός', 'καλύτερος', 'άριστος'],
  ['κακός', 'χειρότερος', 'χείριστος'], ['γρήγορος', 'γρηγορότερος', 'γρηγορότατος'],
  ['δυνατός', 'δυνατότερος', 'δυνατότατος'], ['όμορφος', 'ομορφότερος', 'ομορφότατος'],
  ['ακριβός', 'ακριβότερος', 'ακριβότατος'], ['φτηνός', 'φτηνότερος', 'φτηνότατος'],
  ['βαρύς', 'βαρύτερος', 'βαρύτατος'], ['ελαφρύς', 'ελαφρύτερος', 'ελαφρύτατος'],
  ['πλατύς', 'πλατύτερος', 'πλατύτατος'], ['παλιός', 'παλιότερος', 'παλιότατος'],
  ['νέος', 'νεότερος', 'νεότατος'], ['σοφός', 'σοφότερος', 'σοφότατος'],
  ['πλούσιος', 'πλουσιότερος', 'πλουσιότατος'], ['φτωχός', 'φτωχότερος', 'φτωχότατος'],
  ['ζεστός', 'ζεστότερος', 'ζεστότατος'], ['κρύος', 'κρυότερος', 'κρυότατος'],
]

function genComparativesD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const [positive, comparative, superlative] = pick(COMPARATIVES)
    const askComparative = rng() < 0.55
    const answer = askComparative ? comparative : superlative
    const label = askComparative ? 'συγκριτικός' : 'υπερθετικός'
    const q = `Ποιος είναι ο ${label} βαθμός του επιθέτου «${positive}»;`
    const isMc = rng() < mcRatio
    let opts
    if (isMc) {
      const other = pick(COMPARATIVES.filter((c) => c[0] !== positive))
      opts = mcOptions(answer, [askComparative ? superlative : comparative, positive, askComparative ? other[1] : other[2]])
    }
    const accepted = isMc
      ? undefined
      : askComparative
        ? [`πιο ${positive}`]
        : [`ο πιο ${positive}`, `πολύ ${positive}`, `ο ${comparative}`]
    if (addQ(grammar, 'grammar', isMc ? 'multiple-choice' : 'text', q, answer, opts, accepted)) made++
  }
}

// [ονομαστική με άρθρο, γενική ενικού, γενική πληθυντικού]
const GENITIVES = [
  ['το παιδί', 'του παιδιού', 'των παιδιών'], ['το βιβλίο', 'του βιβλίου', 'των βιβλίων'],
  ['ο δάσκαλος', 'του δασκάλου', 'των δασκάλων'], ['η μητέρα', 'της μητέρας', 'των μητέρων'],
  ['ο πατέρας', 'του πατέρα', 'των πατέρων'], ['η πόλη', 'της πόλης', 'των πόλεων'],
  ['το τραπέζι', 'του τραπεζιού', 'των τραπεζιών'], ['ο φίλος', 'του φίλου', 'των φίλων'],
  ['η θάλασσα', 'της θάλασσας', 'των θαλασσών'], ['το σχολείο', 'του σχολείου', 'των σχολείων'],
  ['ο κήπος', 'του κήπου', 'των κήπων'], ['η αδελφή', 'της αδελφής', 'των αδελφών'],
  ['το παράθυρο', 'του παραθύρου', 'των παραθύρων'], ['ο μαθητής', 'του μαθητή', 'των μαθητών'],
  ['η τάξη', 'της τάξης', 'των τάξεων'], ['το όνομα', 'του ονόματος', 'των ονομάτων'],
  ['ο άνθρωπος', 'του ανθρώπου', 'των ανθρώπων'], ['η χώρα', 'της χώρας', 'των χωρών'],
  ['το δέντρο', 'του δέντρου', 'των δέντρων'], ['ο ουρανός', 'του ουρανού', 'των ουρανών'],
]

function genGenitivesD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const [nom, genS, genP] = pick(GENITIVES)
    const singular = rng() < 0.6
    const answer = singular ? genS : genP
    const q = `Γράψε τη γενική ${singular ? 'ενικού' : 'πληθυντικού'} της λέξης «${nom}».`
    const isMc = rng() < mcRatio
    let opts
    if (isMc) {
      const other = pick(GENITIVES.filter((g) => g[0] !== nom))
      opts = mcOptions(answer, [singular ? genP : genS, nom, singular ? other[1] : other[2]])
    }
    const accepted = isMc ? undefined : [answer.split(' ')[1]]
    const qText = isMc ? `Ποια είναι η γενική ${singular ? 'ενικού' : 'πληθυντικού'} της λέξης «${nom}»;` : q
    if (addQ(grammar, 'grammar', isMc ? 'multiple-choice' : 'text', qText, answer, opts, accepted)) made++
  }
}

const PRONOUNS = ['εγώ', 'εσύ', 'αυτός', 'αυτή', 'εμείς', 'εσείς', 'αυτοί', 'κάποιος', 'κανένας', 'τίποτα', 'ποιος', 'όλοι']

function genPronounsD(n) {
  let made = 0, guard = 0
  while (made < n && guard < n * 20) {
    guard++
    const correct = pick(PRONOUNS)
    const distractors = [pick(NOUNS)[0], pick(ADJECTIVES), pick(VERBS)[0]]
    const q = 'Ποια λέξη είναι αντωνυμία;'
    const opts = shuffle([correct, ...distractors])
    if (addQ(grammar, 'grammar', 'multiple-choice', q, correct, opts)) made++
  }
}

const SYNONYMS_D = [
  ['γρήγορος', 'ταχύς'], ['σπουδαίος', 'σημαντικός'], ['σιωπηλός', 'αμίλητος'],
  ['φωτεινός', 'λαμπερός'], ['καθαρός', 'πεντακάθαρος'], ['δειλός', 'φοβιτσιάρης'],
  ['όμορφος', 'πανέμορφος'], ['κρύος', 'παγωμένος'], ['ζεστός', 'καυτός'],
  ['δρόμος', 'οδός'], ['σπίτι', 'κατοικία'], ['γιατρός', 'ιατρός'],
  ['γιορτή', 'εορτή'], ['σκέφτομαι', 'συλλογίζομαι'],
]

const ANTONYMS_D = [
  ['θάρρος', 'φόβος'], ['εργατικός', 'τεμπέλης'], ['γενναιόδωρος', 'τσιγκούνης'],
  ['ήρεμος', 'νευρικός'], ['αγοράζω', 'πουλάω'], ['ανεβαίνω', 'κατεβαίνω'],
  ['θυμάμαι', 'ξεχνάω'], ['ενώνω', 'χωρίζω'], ['γεμίζω', 'αδειάζω'],
  ['ανάβω', 'σβήνω'], ['δένω', 'λύνω'], ['χτίζω', 'γκρεμίζω'],
  ['νίκη', 'ήττα'], ['αλήθεια', 'ψέμα'], ['ελευθερία', 'σκλαβιά'], ['ομορφιά', 'ασχήμια'],
]

function genSynAntD(n, mcRatio) {
  let made = 0, guard = 0
  while (made < n && guard < n * 30) {
    guard++
    const synMode = rng() < 0.5
    const pairs = synMode ? SYNONYMS_D : ANTONYMS_D
    const pair = pick(pairs)
    const reversed = rng() < 0.5
    const [word, target] = reversed ? [pair[1], pair[0]] : pair
    const isMc = rng() < mcRatio
    const kind = synMode ? 'συνώνυμο' : 'αντίθετο'
    const q = isMc ? `Ποιο είναι το ${kind} της λέξης «${word}»;` : `Γράψε ${synMode ? 'ένα συνώνυμο' : 'το αντίθετο'} της λέξης «${word}».`
    let opts
    if (isMc) {
      const distractors = pickN(pairs.filter((p) => p !== pair), 3).map((p) => pick(p))
      opts = mcOptions(target, distractors)
    }
    if (addQ(grammar, 'grammar', isMc ? 'multiple-choice' : 'text', q, target, opts)) made++
  }
}

