// ==================================================================
// ASSEMBLE — six banks of 500 (Α'-ΣΤ'), ~65% MC each
// ==================================================================

function resetBuckets() {
  math.length = 0
  grammar.length = 0
  spelling.length = 0
  environment.length = 0
  history.length = 0
  religion.length = 0
  geography.length = 0
  science.length = 0
  seenQuestions.clear()
  idCounters = {
    math: 0, grammar: 0, spelling: 0, environment: 0,
    history: 0, religion: 0, geography: 0, science: 0,
  }
}

function summarize(list) {
  const byCat = {}
  for (const q of list) {
    byCat[q.category] ??= { total: 0, mc: 0, text: 0 }
    byCat[q.category].total++
    byCat[q.category][q.type === 'multiple-choice' ? 'mc' : 'text']++
  }
  return byCat
}

function assembleAndWrite(outPath, label) {
  const BASE_TOTAL = 500
  const MATH_TARGET = 210
  const GRAMMAR_TARGET = 140
  const ENV_TARGET = 47
  // history/religion/geography/science only exist for grades where the
  // corresponding bucket was filled (Γ'-ΣΤ' for history/religion, Ε'-ΣΤ' for
  // geography/science) — buckets stay empty otherwise, so this is purely
  // additive on top of the original 500 and leaves Α'/Β' untouched.
  const NEW_SUBJECT_TARGET = 50

  const finalEnvironment = shuffle(environment).slice(0, ENV_TARGET)
  const finalHistory = shuffle(history).slice(0, NEW_SUBJECT_TARGET)
  const finalReligion = shuffle(religion).slice(0, NEW_SUBJECT_TARGET)
  const finalGeography = shuffle(geography).slice(0, NEW_SUBJECT_TARGET)
  const finalScience = shuffle(science).slice(0, NEW_SUBJECT_TARGET)
  const SPELLING_TARGET = BASE_TOTAL - MATH_TARGET - GRAMMAR_TARGET - finalEnvironment.length

  const all = shuffle([
    ...shuffle(math).slice(0, MATH_TARGET),
    ...shuffle(grammar).slice(0, GRAMMAR_TARGET),
    ...shuffle(spelling).slice(0, SPELLING_TARGET),
    ...finalEnvironment,
    ...finalHistory,
    ...finalReligion,
    ...finalGeography,
    ...finalScience,
  ])

  const counters = {
    math: 0, grammar: 0, spelling: 0, environment: 0,
    history: 0, religion: 0, geography: 0, science: 0,
  }
  for (const q of all) {
    counters[q.category]++
    q.id = `${gradePrefix}-${CATEGORY_ID_PREFIX[q.category]}${counters[q.category]}`
  }

  writeFileSync(outPath, JSON.stringify(all, null, 2) + '\n', 'utf-8')
  const mcTotal = all.filter((q) => q.type === 'multiple-choice').length
  console.log(`[${label}] total: ${all.length}, MC: ${((mcTotal / all.length) * 100).toFixed(1)}%`)
  console.log(JSON.stringify(summarize(all)))
}

